def timer(fn):
    import time
    def wrapper(*a, **k):
        t = time.perf_counter()
        r = fn(*a, **k)
        print(f"{fn.__name__}: {time.perf_counter() - t:.4f}s")
        return r
    return wrapper

@timer
def work():
    sum(range(10**6))
work()

from functools import wraps
def log(fn):
    @wraps(fn)
    def w(*a, **k):
        print("call", fn.__name__)
        return fn(*a, **k)
    return w

def repeat(n):
    def deco(fn):
        def w(*a, **k):
            for _ in range(n): fn(*a, **k)
        return w
    return deco

class Timer:
    def __enter__(self):
        import time; self.t = time.time(); return self
    def __exit__(self, *exc):
        import time; print(time.time() - self.t)
with Timer():
    sum(range(10**6))

